create extension if not exists pgcrypto;
create type public.user_role as enum ('t1d','caregiver','supporter','organization');
create type public.help_status as enum ('open','matched','closed','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,role public.user_role not null default 'caregiver',bio text default '',city text,region text,avatar_url text,helper_enabled boolean not null default false,created_at timestamptz not null default now());
create table public.approximate_locations(user_id uuid primary key references public.profiles(id) on delete cascade,geohash_prefix text not null,city text,region text,updated_at timestamptz not null default now());
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,body text not null,category text not null default 'General',created_at timestamptz not null default now());
create table public.help_requests(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id) on delete cascade,kind text not null,item text not null,details text default '',urgency text not null default 'today',radius_miles int not null default 15,status public.help_status not null default 'open',created_at timestamptz not null default now());
create table public.beacon_responses(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.help_requests(id) on delete cascade,responder_id uuid not null references public.profiles(id) on delete cascade,message text default 'I can help',created_at timestamptz not null default now(),unique(request_id,responder_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now());
create table public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table public.blocks(blocker_id uuid references public.profiles(id) on delete cascade,blocked_id uuid references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(blocker_id,blocked_id));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,target_type text not null,target_id uuid not null,reason text not null,details text default '',created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.approximate_locations enable row level security;alter table public.posts enable row level security;alter table public.help_requests enable row level security;alter table public.beacon_responses enable row level security;alter table public.conversations enable row level security;alter table public.conversation_members enable row level security;alter table public.messages enable row level security;alter table public.blocks enable row level security;alter table public.reports enable row level security;
create policy "profiles read" on public.profiles for select to authenticated using(true);
create policy "profile own update" on public.profiles for update to authenticated using(auth.uid()=id);
create policy "location own" on public.approximate_locations for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "posts read" on public.posts for select to authenticated using(true);
create policy "posts insert own" on public.posts for insert to authenticated with check(auth.uid()=author_id);
create policy "help read" on public.help_requests for select to authenticated using(true);
create policy "help insert own" on public.help_requests for insert to authenticated with check(auth.uid()=requester_id);
create policy "response insert own" on public.beacon_responses for insert to authenticated with check(auth.uid()=responder_id);
create policy "conversations member read" on public.conversations for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=conversations.id and cm.user_id=auth.uid()));
create policy "conversation members own read" on public.conversation_members for select to authenticated using(user_id=auth.uid());
create policy "messages member read" on public.messages for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));
create policy "messages member insert" on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));
create policy "blocks own" on public.blocks for all to authenticated using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
create policy "reports own insert" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','T1Together Member'),coalesce((new.raw_user_meta_data->>'role')::public.user_role,'caregiver'));return new;end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();